/** Domain schema reference. Runtime validation lives in engine.js and storage.js. */
export type LocalDate = string; // YYYY-MM-DD, separate from an instant
export type UTCInstant = string; // ISO 8601 Z
export type Source = 'manual' | 'synthetic' | 'strava'; // Strava records and derived plans are memory-only.
export interface Goal { goal: 'fitness'|'endurance'|'event'|'climbing'|'racing'|'consistency'; eventDate: LocalDate|''; eventDistanceKm: number|null; eventTerrain: string; eventDurationMinutes: number|null }
export interface Availability { availability: number[]; timezone: string; otherExerciseDays: number[] } // Sunday-first minutes, 0 = rest
export type Equipment = 'bicycle'|'trainer'|'power'|'hr'|'cadence';
export interface ThresholdAssessment { watts: number; method: 'test'|'estimate'; date: LocalDate; version?: string }
export interface ZoneDefinition { targetMethod: 'RPE-talk-test-v1'|'FTP-reference-with-RPE-coach-2.0'|'FTP-watts-coach-2.1'; thresholdVersion: string|null } // Power references are prescription guides; no inferred HR zones
export interface RiderProfile extends Goal, Availability { name: string; strength?: StrengthSettings; coach?: CoachIntake; bodyMassKg?: number|null; maxHeartRate?: number|null; experience: 'new'|'returning'|'consistent'; weeklyMinutes: number; weeklyTargetMinutes?: number|null; longestMinutes: number; availabilityAssumed?: boolean; personalSetupVersion?: number; units: 'metric'|'imperial'; preference: 'inside'|'outside'|'either'; equipment: Equipment[]; threshold: ThresholdAssessment|null; recovery: 'normal'|'poor'; recoveryWeekEnd?: LocalDate|''; limitation: 'none'|'restricted'|'acute'; retentionDays: 30|90|365 }
export interface WorkoutStep { title: string; minutes: number; repetitions: number; target: number; unit: 'RPE / 10'|'W'; intensity?: 'easy'|'work'; guidance: string; powerTarget?: {targetWatts?:number;minWatts:number;maxWatts:number;minPercent:number;maxPercent:number;unit:'W';method:'FTP-reference-coach-2.0';thresholdWatts:number;thresholdDate:LocalDate} }
export interface SensorSummary { elapsedSeconds: number|null; elevationMeters: number|null; estimatedCalories: number|null; providerRelativeEffort: number|null; averageCadence: number|null; temperatureC: number|null; trainer: boolean|null; power: { averageWatts: number|null; maxWatts: number|null; weightedWatts: number|null; workKj: number|null; deviceWatts: boolean|null; source: 'device'|'estimated'|'unknown'|'missing' }; heartRate: { recorded: boolean; averageBpm: number|null; maxBpm: number|null }; deviceName?: string|null; laps?: Array<{index:number; name:string; elapsedSeconds:number|null; movingSeconds:number|null; averageWatts:number|null; averageBpm:number|null}> }
export interface SignalStatistics { seconds:number; mean:number|null; max:number|null; cv:number|null; histogram:Array<[number,number]> }
export interface SignalAnalysis { version:string; sampleCount:number; recordedSeconds:number; activeSeconds:number; gapSeconds:number; power:SignalStatistics & {source:string; best:Array<{seconds:number;watts:number|null;maxSampleStep?:number}>}; heartRate:SignalStatistics; cadence:SignalStatistics; temperature:SignalStatistics; workKj:number|null; drift:{eligible:boolean;percent:number|null;reason:string}; quality:string[]; plot:Array<{seconds:number;watts:number|null;bpm:number|null;cadence:number|null}> }
export interface EnrichmentProgress { details:'pending'|'ready'|'retry'|'unavailable'|'failed'; streams:'pending'|'ready'|'retry'|'unavailable'|'failed'; attempts:number; error:string; fetchedAt:number|null }
export interface Activity { id: string; date: LocalDate; title: string; minutes: number; distanceKm: number|null; rpe: number|null; discipline: 'cycling'|'other'; source: Source; recordedAt: UTCInstant; sensors?:SensorSummary|null; signals?:SignalAnalysis|null; enrichment?:EnrichmentProgress|null }
export interface WorkoutFeedback { actualMinutes: number; feeling: 'comfortable'|'hard'|'poor'; recordedAt?: UTCInstant }
export interface Workout extends ZoneDefinition { id: string; date: LocalDate; timezone: string; title: string; discipline: 'cycling'; purpose: string; minutes: number; equipment: Equipment[]; steps: WorkoutStep[]; alternative: string; status: 'planned'|'completed'|'partial'|'skipped'|'modified'; locked: boolean; activityId: string|null; feedback: WorkoutFeedback|null }
export interface TrainingPlan { id: string; startDate: LocalDate; timezone: string; version: string; generatedAt: UTCInstant; workouts: Workout[]; reasons: string[]; conflicts: string[]; evidenceIds: string[]; budget: number; total: number }
export interface PlanChange { id: string; date: LocalDate; before: string; after: string }
export interface AdaptationDecision { id: string; plan: TrainingPlan; profile: RiderProfile; reason: string; diff: PlanChange[]; baseRevision: number }
export interface PlanRevision { id: string; at: UTCInstant; reason: string; before: TrainingPlan|null; after: TrainingPlan|null; profileBefore?: RiderProfile; profileAfter?: RiderProfile; changes: PlanChange[]; undone?: boolean }
export interface IntegrationConnection { provider: 'strava'; status: 'unavailable' } // Never means externally connected
export interface AppState { strengthRoom?: StrengthRoom; schema: 1; revision: number; onboarded: boolean; mode: Source; profile: RiderProfile; activities: Activity[]; plan: TrainingPlan|null; revisions: PlanRevision[]; processedEvents: string[]; connection: IntegrationConnection }

export interface CoachIntake { confirmed:boolean; focus: 'endurance'|'sustained'|'climbing'|'race'|'fitness'; goalDetail:string; cycleStart:LocalDate; checkInDate:LocalDate; fatigue:number; soreness:number; sleep:number; motivation:number; intervalExperience:'unknown'|'none'|'one'|'two'; strengthDays?:number[] }

export interface StrengthSettings {confirmed:boolean;equipment:'gym'|'dumbbells'|'bodyweight';experience:'unknown'|'new'|'regular';thursdayMinutes:number;sundayMinutes:number;restrictions:'unknown'|'none'|'restricted';loadNotes?:string}
export interface StrengthFeedback {sessionId:string;date:LocalDate;status:'completed'|'partial'|'modified'|'skipped';actualMinutes:number;soreness:number;pain:boolean;notes:string;recordedAt?:UTCInstant}

export interface StrengthExercise {id:string;title:string;sets:number;reps:string;restSeconds:number;minutes:number;tempo:string;load:string;cues:string[];alternative:string}
export interface StrengthSession {id:string;date:LocalDate;timezone:string;version:string;title:string;purpose:string;equipment:string;minutes:number;availableMinutes:number;ready:boolean;paused:boolean;reduced:boolean;loadNotes:string;warmup:{minutes:number;instructions:string};cooldown:{minutes:number;instructions:string};exercises:StrengthExercise[];coordination:string;progression:string;easier:string}
export interface StrengthPlan {id:string;startDate:LocalDate;version:string;sessions:StrengthSession[];canAccept:boolean;reasons:string[];revision:number;acceptedAt?:UTCInstant;reason?:string}
export interface StrengthRoom {plans:StrengthPlan[];records:StrengthFeedback[]}
